function initTabs(){const t=document.querySelectorAll(".tab-btn"),e=document.querySelectorAll(".tab-content");t.forEach(a=>{a.addEventListener("click",()=>{t.forEach(t=>{t.classList.remove("active"),t.setAttribute("aria-selected","false")}),e.forEach(t=>t.classList.remove("active")),a.classList.add("active"),a.setAttribute("aria-selected","true"),document.getElementById(a.getAttribute("data-tab")).classList.add("active")})})}function initQuiz(){const t=document.getElementById("kakatiya-quiz-form"),e=document.getElementById("quiz-result"),a={q1:"2",q2:"2"};t&&t.addEventListener("submit",i=>{i.preventDefault();let n=0;const o=new FormData(t);for(let[t,e]of o.entries())a[t]===e&&n++;const l=Object.keys(a).length;e.textContent=n===l?`🎉 Perfect! ${n}/${l}`:`You scored ${n}/${l}`,e.style.color=n===l?"green":"orange"})}function initGalleryModal(){const t=document.getElementById("gallery-modal"),e=document.getElementById("modal-title"),a=document.getElementById("modal-desc"),i=document.querySelector(".modal-close");document.querySelectorAll(".gallery-item").forEach(i=>{i.addEventListener("click",()=>{e.textContent=i.getAttribute("data-title"),a.textContent=i.getAttribute("data-desc"),t.classList.add("active")})}),i&&i.addEventListener("click",()=>t.classList.remove("active")),window.addEventListener("click",e=>{e.target===t&&t.classList.remove("active")})}function initScrollTop(){const t=document.getElementById("btn-scroll-top");t&&(window.addEventListener("scroll",()=>t.classList.toggle("visible",window.scrollY>300)),t.addEventListener("click",()=>window.scrollTo({top:0,behavior:"smooth"})))}function registerJourneyItems(){window.Journey&&window.Journey.registerSearchItems&&window.Journey.registerSearchItems("kakatiya-dynasty/index.html",[{id:"kakatiya-ramappa",title:"Ramappa Temple",description:"UNESCO World Heritage site built by Kakatiyas.",link:"kakatiya-dynasty/index.html#architecture"},{id:"kakatiya-rudrama",title:"Rudrama Devi",description:"Famous female ruler of the Kakatiya dynasty.",link:"kakatiya-dynasty/index.html#rulers"}])}document.addEventListener("DOMContentLoaded",()=>{initTabs(),initQuiz(),initGalleryModal(),initScrollTop(),registerJourneyItems()});